<?php $e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); ?>
<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Benachrichtigungen – MeldeVerkehr</title>
<style>body{font-family:system-ui,sans-serif;background:#f5f7fa;color:#172033;margin:0}main{max-width:900px;margin:28px auto;padding:20px}.card{background:#fff;border:1px solid #dfe5ec;border-radius:15px;padding:20px;margin-bottom:14px}.item{border-top:1px solid #e5e9ee;padding:13px 0}.unread{font-weight:700}.priority{display:inline-block;padding:3px 7px;border-radius:999px;background:#edf1f5;font-size:.8rem}button,.button{display:inline-block;padding:8px 12px;border:0;border-radius:8px;background:#172033;color:#fff;text-decoration:none;font-weight:700}.muted{color:#66758a}</style></head><body><main>
<p><a href="/dashboard">Dashboard</a> · <a href="/search">Suche</a> · <a href="/notifications/settings">Einstellungen</a></p><h1>Benachrichtigungen</h1><p><strong><?= $e($unreadCount) ?></strong> ungelesen</p>
<form method="post" action="/notifications/read-all"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Alle als gelesen markieren</button></form>
<section class="card"><?php foreach($notifications as $n):?><div class="item <?= $n['read_at']===null?'unread':'' ?>"><span class="priority"><?= $e($n['priority']) ?></span> <strong><?= $e($n['title']) ?></strong><p><?= $e($n['body']??'') ?></p><small class="muted"><?= $e($n['created_at']) ?></small><p><?php if($n['action_url']):?><a class="button" href="<?= $e($n['action_url']) ?>">Öffnen</a><?php endif;?><?php if($n['read_at']===null):?> <form style="display:inline" method="post" action="/notifications/<?= rawurlencode($n['id']) ?>/read"><input type="hidden" name="_csrf" value="<?= $e($csrf) ?>"><button type="submit">Gelesen</button></form><?php endif;?></p></div><?php endforeach;?><?php if(!$notifications):?><p class="muted">Keine Benachrichtigungen.</p><?php endif;?></section>
</main><script src="/assets/app.js" defer></script></body></html>